from dataclasses import dataclass

@dataclass
class Order:
    id: str
    total: Decimal = Decimal(0)
    lines: int = 1

def read_order(payload: dict) -> Order:
    return Order(id=payload["id"],                      # required: raises if missing
                 total=Decimal(payload.get("total", 0)),
                 lines=payload.get("lines", 1))         # unknown keys ignored
